abstract class TFMPageConfiguration
{
    str					         type;
    boolean                      useType;
    boolean                      offlineEnabled;
    str                          warnOnNavigationBackMessage;
    str                          warnOnNavigationBackTitle;
    TFMOverDeliveryValidation    warnOnNavigationBackWarningType;
    str                          warnOnNavigationBackNotifyBackendDocument;
    str					         filterName;
    str					         pageName;

}

Method.Source:
public str parmType(str _type = type)
{
    type = _type;

    return type;
}

/// <summary>
/// Warning title on the warn on navigation back configuration.
