[TFMPageConfigurationAttributeAttribute('','warnOnNavigatingBack', 'title', false, true, false, false, true)]
public TFMLocalizedStringEDT parmWarnOnNavigationBackTitle(TFMLocalizedStringEDT _warnOnNavigationBackTitle = warnOnNavigationBackTitle)
{
    warnOnNavigationBackTitle = _warnOnNavigationBackTitle;
    return warnOnNavigationBackTitle;
}

